<?php require 'config.php'; require 'lib.php'; need_login(); track_user(); csrf_check(); if($_SERVER['REQUEST_METHOD']==='POST'&&!is_admin()){ http_response_code(403); exit(t('Du har bara läsbehörighet.','You have read-only access.')); }
if($_SERVER['REQUEST_METHOD']==='POST'){ $pdo=db();
 if(($_POST['a']??'')==='add'&&trim($_POST['host'])!==''){
  $pdo->prepare('INSERT INTO servers(name,host) VALUES(?,?)')->execute([trim($_POST['name'])?:trim($_POST['host']),trim($_POST['host'])]); $id=$pdo->lastInsertId();
  $pdo->prepare("INSERT INTO server_checks(server_id,source,kind,target,label) VALUES(?,'tcp','ping','','Ping')")->execute([$id]); $sv=$_POST['snmp']??''; if($sv===''&&trim($_POST['community']??'')!=='') $sv='2';
  if($sv==='2'||$sv==='3') $pdo->prepare("INSERT INTO server_checks(server_id,source,kind,target,param,label) VALUES(?,'snmp','all','',?,'SNMP')")->execute([$id,$sv==='3'?snmp_param_build('3',$_POST,''):(trim($_POST['community']??'')?:'default')]);
  applog('info','config','Server added: '.trim($_POST['name']?:$_POST['host']).' ('.trim($_POST['host']).')'); header('Location: servers.php?added=1');exit; }
 if(($_POST['a']??'')==='edit'){ $h=trim($_POST['host']??''); if($h!==''){ $pdo->prepare('UPDATE servers SET name=?,host=?,comment=? WHERE id=? AND is_services=0')->execute([trim($_POST['name']??'')?:$h,$h,trim($_POST['comment']??''),(int)$_POST['id']]); if(isset($_POST['zbx_mode'])){ try{ $zh=trim((string)($_POST['zbx_host']??'')); $pdo->prepare('UPDATE servers SET zbx_active=?,zbx_host=? WHERE id=? AND is_services=0')->execute([$_POST['zbx_mode']==='active'?1:0,$zh===''?null:mb_substr($zh,0,120),(int)$_POST['id']]); zbxa_map(true); }catch(Throwable $e){ $_SESSION['flash']=t('Kör SQL-migreringen (sql/3.10.sql) först.','Run the SQL migration (sql/3.10.sql) first.'); } } } header('Location: servers.php');exit; }
 if(($_POST['a']??'')==='toggle_dash'){ $pdo->prepare('UPDATE servers SET dash_hidden=1-dash_hidden WHERE id=? AND is_services=0 AND hv_type IS NULL AND nw_type IS NULL')->execute([(int)$_POST['id']]); header('Location: servers.php');exit; }
 if(($_POST['a']??'')==='toggle_enabled'){ $sid=(int)$_POST['id']; $pdo->prepare('UPDATE servers SET enabled=1-enabled WHERE id=? AND is_services=0')->execute([$sid]); $pdo->prepare('UPDATE server_checks SET last_check=NULL WHERE server_id=? AND (SELECT enabled FROM servers WHERE id=?)=1')->execute([$sid,$sid]); header('Location: servers.php');exit; }
 if(($_POST['a']??'')==='del'){ $did=(int)$_POST['id']; $q=$pdo->prepare('SELECT id FROM server_checks WHERE server_id=?'); $q->execute([$did]); purge_targets([$did],array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN))); applog('warning','config','Server deleted, id '.$did); $pdo->prepare('DELETE FROM servers WHERE id=?')->execute([$did]); header('Location: servers.php');exit; }
}
$ed=null; if(isset($_GET['edit'])&&is_admin()){ $q=db()->prepare('SELECT * FROM servers WHERE id=? AND is_services=0'); $q->execute([(int)$_GET['edit']]); $ed=$q->fetch()?:null; }
top(t('Servrar','Servers')); ?>
