<?php $MM=[]; foreach(db()->query('SELECT c.* FROM server_checks c JOIN servers s ON s.id=c.server_id WHERE s.is_services=0 AND s.hv_type IS NULL AND s.nw_type IS NULL AND c.enabled=1 ORDER BY c.id') as $c) $MM[$c['server_id']][]=$c; ?>
<?php foreach(db()->query("SELECT s.*,(SELECT last_status FROM server_checks c WHERE c.server_id=s.id AND c.source='tcp' AND c.kind='ping' LIMIT 1) ping FROM servers s WHERE s.is_services=0 AND s.hv_type IS NULL AND s.nw_type IS NULL ORDER BY s.name") as $s): ?>
<tr class="<?= ($s['enabled']??1)?'':'dim' ?>" data-href="server.php?id=<?= $s['id'] ?>"><td><b class="rn"><?= h($s['name']) ?></b><?= ($s['enabled']??1)?'':' <small>('.t('inaktiverad','disabled').')</small>' ?><?= !empty($s['dash_hidden'])?' <small>('.t('dold på dash','hidden on dash').')</small>':'' ?><?= trim((string)($s['comment']??''))!==''?'<br><small class="mut">'.h(strlen($s['comment'])>90?substr($s['comment'],0,90).'…':$s['comment']).'</small>':'' ?></td><td><?= h($s['host']) ?></td><td><?= h($s['os_info']?:'–') ?></td><td class="<?= $s['ping']==='up'?'okt':($s['ping']?'badt':'') ?>"><?= $s['ping']?:t('väntar','pending') ?></td><?php $mt=($s['ping']==='down'||!($s['enabled']??1))?['cpu'=>null,'mem'=>null]:srv_metrics($MM[$s['id']]??[]); echo bar_cell($mt['cpu'],'cpu'),bar_cell($mt['mem'],'mem'); ?><td class="ctr"><?= count($MM[$s['id']]??[]) ?></td><?php $inf=json_decode((string)($s['info']??''),true)?:[]; $ifr=$IFS[$s['id']]??[]; $kv=trim((string)($inf['kernel']??'')); if($kv===''&&preg_match('/Build\s+(\d+)/i',(string)($inf['descr']??''),$bm)) $kv='Build '.$bm[1];
 echo tc_td(!empty($inf['uptime'])?tc_upt($inf['uptime']):null,(int)($inf['uptime']??0)),tc_td($kv),tc_topif($ifr),tc_td($ifr?count(array_filter($ifr,fn($x)=>(int)$x['oper']===1)).' / '.count($ifr):null);
echo disk_bar_cell($mt['disks']??[]);
 $cl=$MM[$s['id']]??[]; $cb=count(array_filter($cl,fn($x)=>$x['last_status']==='down')); echo $cl?'<td class="'.($cb?'badt':'okt').'" data-sort="'.$cb.'">'.$cb.' / '.count($cl).'</td>':'<td class="mut">–</td>';
 echo tc_td($inf['hostname']??null),tc_td(is_array($inf['ips']??null)?implode(', ',$inf['ips']):($inf['ips']??null)),tc_td($s['comment']??null); ?>
<?= dg_td($s['id']) ?><?= dg_tds($s['id']) ?><td class="inline"><?php if(is_admin()): ?><a class="btn sm" href="servers.php?edit=<?= $s['id'] ?>"><?= t('Ändra','Edit') ?></a><form method="post"><?= csrf_field() ?><input type="hidden" name="a" value="toggle_enabled"><input type="hidden" name="id" value="<?= $s['id'] ?>"><button class="btn sm <?= ($s['enabled']??1)?'warn':'go' ?>"><?= ($s['enabled']??1)?t('Inaktivera','Disable'):t('Aktivera','Enable') ?></button></form><form method="post" onsubmit="return confirm('<?= t('Ta bort servern och all dess data?','Delete the server and all its data?') ?>')"><?= csrf_field() ?><input type="hidden" name="a" value="del"><input type="hidden" name="id" value="<?= $s['id'] ?>"><button class="btn danger sm"><?= t('Ta bort','Delete') ?></button></form><?php endif; ?></td></tr>
